'use strict';
const artNames=['cindercub','mossprout','ripplefin','voltwing','duskhorn','pebblit','frostuft','bloomtail','soloryx'];
const creatureArt=artNames.map(name=>{const img=new Image();img.src='art/'+name+'.png';return img});
mon=function(c,id,x,y,scale=3,t=0,flip=false){const img=creatureArt[id],i=identity(id);c.save();c.translate(x,y+Math.sin(t)*scale*.7);if(flip)c.scale(-1,1);const isGame=c.canvas===canvas;let maxW=isGame?scale*54:Math.min(scale*54,c.canvas.width*.9),maxH=isGame?scale*54:Math.min(scale*54,c.canvas.height*.86);const ratio=img.naturalWidth&&img.naturalHeight?img.naturalWidth/img.naturalHeight:1;let w=maxW,h=w/ratio;if(h>maxH){h=maxH;w=h*ratio}const bottom=scale*12;c.globalAlpha*=.22;c.fillStyle='#081b16';c.beginPath();c.ellipse(0,bottom,w*.32,Math.max(3,scale*2),0,0,Math.PI*2);c.fill();c.globalAlpha/=.22;c.imageSmoothingEnabled=true;c.filter=`hue-rotate(${i.hue*.4}deg)`;if(img.complete&&img.naturalWidth){c.drawImage(img,-w/2,bottom-h,w,h)}else{c.fillStyle=species[id].color;c.beginPath();c.ellipse(0,bottom-22*scale,13*scale,19*scale,0,0,Math.PI*2);c.fill();c.fillStyle=species[id].accent;c.beginPath();c.arc(5*scale,bottom-31*scale,5*scale,0,Math.PI*2);c.fill()}c.filter='none';c.restore()};
for(const img of creatureArt)img.onload=()=>{updateUI();if(!$('collection').classList.contains('hidden'))collection();if(!$('market').classList.contains('hidden'))signature();team()};
const oldTick3=tick,oldStart3=start,oldFinish3=finish;let practiceHits=0,practiceCompleted=false,practiceCountedDamage=0;
function practiceUI(){const reward=Math.min(100,practiceHits)*.001+(practiceCompleted ? 0.01 : 0);$('practiceReward').textContent=reward.toFixed(3)+' MNRG';$('practiceDetail').textContent=practiceHits+' practice hits · '+(practiceCompleted?'match complete':'match in progress')+' · no blockchain reward issued'}
start=function(){practiceHits=0;practiceCompleted=false;practiceCountedDamage=0;duel.hits=0;oldStart3();practiceUI()};$('start').onclick=()=>start();
tick=function(dt){oldTick3(dt);if(mode==='duel'&&duel.hits!==practiceHits){practiceHits=duel.hits||0;practiceUI()}};
finish=function(win=false){if(mode==='duel'){practiceCompleted=win||!save.owned.slice(0,6).some(id=>id!==save.selected&&duel.teamHP[id]!==0)&&player.hp<=0;practiceUI()}oldFinish3(win)};
function nftStatus(text,error=false){$('chainOutput').textContent=text;$('chainOutput').classList.toggle('error',error)}
const nftRecordKey='pocketmonstars-devnet-assets-v1';function remember(record){try{const all=JSON.parse(localStorage.getItem(nftRecordKey)||'[]');all.unshift(record);localStorage.setItem(nftRecordKey,JSON.stringify(all.slice(0,50)))}catch(e){}}
function friendlyError(e){const msg=e?.message||String(e);if(/4001|reject|declin/i.test(msg))return 'Wallet request declined. Check the wallet for any submitted signature before retrying.';return msg.slice(0,600)}
function showReview(title,lines,action){$('reviewTitle').textContent=title;$('reviewBody').textContent=lines;$('reviewConfirm').disabled=false;$('reviewConfirm').textContent='Continue to Phantom';$('reviewConfirm').onclick=async()=>{const b=$('reviewConfirm');b.disabled=true;b.textContent='Waiting for wallet / network…';try{await action();$('chainReview').close()}catch(e){$('reviewBody').textContent=lines+'\n\n'+friendlyError(e);b.disabled=false;b.textContent='Try again'}};$('chainReview').showModal()}
$('reviewClose').onclick=()=>$('chainReview').close();document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-work]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelectorAll('.work-view').forEach(v=>v.classList.toggle('hidden',v.id!=='work-'+b.dataset.work))});
function mustConnect(){if(!connectedAddress){openWallet();return false}if(!window.PMChain){nftStatus('Blockchain tools are loading. Refresh if this persists.',true);return false}return true}
function explorerURL(signature){return 'https://explorer.solana.com/tx/'+encodeURIComponent(signature)+'?cluster=devnet'}
function resultStatus(result,label){nftStatus(label+'\n'+(result.confirmed?'Confirmed on devnet.':'Submitted; confirmation is pending. Do not repeat the action until you check this signature.')+'\nSignature: '+result.signature+'\n'+explorerURL(result.signature)+(result.asset?'\nAsset: '+result.asset:''))}
$('inspectNFT').onclick=async()=>{if(!mustConnect())return;const b=$('inspectNFT');b.disabled=true;nftStatus('Fetching devnet asset…');try{const a=await PMChain.inspectAsset($('inspectAsset').value.trim());nftStatus(JSON.stringify(a,null,2))}catch(e){nftStatus(friendlyError(e),true)}finally{b.disabled=false}};
$('mintNFT').onclick=()=>{if(!mustConnect())return;const id=save.selected,uri=$('metadataURI').value.trim();try{const u=new URL(uri);if(u.protocol!=='https:')throw Error('Use a public HTTPS metadata URL.')}catch(e){nftStatus('A valid public HTTPS metadata JSON URL is required.',true);return}const dna=identity(id).dna;const name=species[id].name+' #'+dna.slice(0,8);showReview('Mint a devnet test Monstar',`Name: ${name}\nCreator / owner: ${connectedAddress}\nClass: ${classes[id]}\nDNA: ${dna}\nMetadata: ${uri}\nCreator royalty in this sale flow: 1%\nCompany mint fee: 0\nNetwork rent / protocol fees: additional test SOL, shown by Phantom\nUnverified standalone test NFT; not the official collection.`,async()=>{const r=await PMChain.mintTest({name,uri,dna,className:classes[id],speciesName:species[id].name});resultStatus(r,'Test NFT mint');remember({asset:r.asset,signature:r.signature,name});if(r.confirmed){$('inspectAsset').value=r.asset;$('giftAsset').value=r.asset;$('sellAsset').value=r.asset}})};
$('giftNFT').onclick=async()=>{if(!mustConnect())return;const asset=$('giftAsset').value.trim(),recipient=$('giftRecipient').value.trim();try{const a=await PMChain.inspectAsset(asset);if(a.owner!==connectedAddress)throw Error('You do not own this devnet NFT.');showReview('Gift this devnet Monstar',`NFT: ${a.name}\nAsset: ${asset}\nFrom: ${connectedAddress}\nTo: ${recipient}\nSale price / royalty / company fee: 0\nNetwork fee: shown by Phantom\nRecipient will control the asset after confirmation.`,async()=>{const r=await PMChain.gift(asset,recipient);resultStatus(r,'NFT gift')})}catch(e){nftStatus(friendlyError(e),true)}};
$('sellNFT').onclick=async()=>{if(!mustConnect())return;const price=parseSOL($('sellPrice').value.trim());if(price===null||price<=0n||price>10000000000n){nftStatus('Enter a positive test price up to 10 SOL, at most 9 decimals.',true);return}const asset=$('sellAsset').value.trim(),buyer=$('sellBuyer').value.trim(),treasury=$('sellTreasury').value.trim();try{const a=await PMChain.inspectAsset(asset);if(a.owner!==connectedAddress)throw Error('You do not own this NFT.');showReview('Sign a private devnet sale offer',`NFT: ${a.name}\nAsset: ${asset}\nBuyer: ${buyer}\nPrice: ${formatSOL(price)}\nCreator royalty: ${a.royaltyBps} basis points from on-chain metadata\nCompany treasury: ${treasury||'Not configured; no company fee'}\nCompany fee: ${treasury?'1 lamport':'0'}\nThis signature transfers the asset ONLY when this exact buyer also signs and pays. Offer expires shortly.`,async()=>{const r=await PMChain.createOffer({asset,buyer,priceLamports:price.toString(),treasury:treasury||null});$('saleOffer').value=JSON.stringify(r.offer);nftStatus('Signed private devnet offer created. No sale is completed yet. Copy it to the named buyer before expiry.\n'+JSON.stringify(r.summary,null,2))})}catch(e){nftStatus(friendlyError(e),true)}};
$('copyOffer').onclick=async()=>{if(!$('saleOffer').value){nftStatus('Create an offer first.',true);return}try{await navigator.clipboard.writeText($('saleOffer').value);toast('Offer copied. Send it to the named buyer.')}catch(e){$('saleOffer').select();toast('Select and copy the offer text.')}};
$('reviewNFT').onclick=async()=>{if(!mustConnect())return;try{const raw=$('buyOffer').value;if(raw.length>10000)throw Error('Offer is too large.');const offer=JSON.parse(raw),r=await PMChain.reviewOffer(offer),s=r.summary;showReview('Buy this devnet Monstar',`NFT: ${s.name}\nAsset: ${s.asset}\nSeller: ${s.seller}\nBuyer: ${s.buyer}\nTotal price: ${formatSOL(BigInt(s.priceLamports))}\nSeller receives: ${formatSOL(BigInt(s.sellerLamports))}\nCreator royalty: ${formatSOL(BigInt(s.royaltyLamports))}\nCompany fee: ${formatSOL(BigInt(s.companyLamports))}\nCompany treasury: ${s.treasury||'None'}\nNetwork fee: additional, shown by Phantom\nSeller signature and exact instructions verified. NFT transfer and all payments are atomic.`,async()=>{const result=await PMChain.acceptOffer(offer);resultStatus(result,'Private NFT purchase')})}catch(e){nftStatus(friendlyError(e),true)}};
$('createToken').onclick=()=>{if(!mustConnect())return;showReview('Create a devnet reward-token mint',`Network: Solana devnet only\nDraft token: Monstar Energy (MNRG)\nStandard SPL Token mint; name metadata not uploaded\nDecimals: 9\nFixed supply: 1,000,000,000 tokens\nInitial recipient: ${connectedAddress}\nMint authority: revoked in this transaction\nFreeze authority: none\nTest SOL required for account rent and network fees.\nThis creates a new independent test mint, not an official production reward token.`,async()=>{const r=await PMChain.createRewardMint();$('tokenOutput').textContent=(r.confirmed?'Confirmed test mint.':'Submitted; confirmation pending. Do not create another mint until checked.')+'\nMint: '+r.mint+'\nTreasury token account: '+r.treasury+'\nSignature: '+r.signature+'\n'+explorerURL(r.signature);remember({mint:r.mint,signature:r.signature,kind:'reward-test-mint'});resultStatus(r,'Test reward token')})};
const baseTab3=tab;tab=function(id){baseTab3(id);if(id==='rewards')practiceUI()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
practiceUI();renderMoves();team();updateUI();
